(x, y, t) => {
  const cx = 240, cy = 120;
  const attractors = [
    [160+Math.sin(t*0.5)*120, 80+Math.cos(t*0.3)*60, 3.5],
    [320+Math.cos(t*0.4)*100, 160+Math.sin(t*0.6)*80, 2.8],
    [240+Math.sin(t*0.25+2)*140, 120+Math.cos(t*0.45+1)*100, 4.0],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.5+3)*70, 2.2],
    [380+Math.sin(t*0.35+4)*80, 50+Math.cos(t*0.8+2)*60, 3.2],
    [200+Math.cos(t*0.3+5)*110, 200+Math.sin(t*0.5)*90, 2.5]
  ];
  let gx = 0, gy = 0, potential = 0;
  for (const [ax, ay, mass] of attractors) {
    const dx = ax - x, dy = ay - y;
    const dist = Math.sqrt(dx*dx + dy*dy) + 1;
    const force = mass / (dist * 0.1);
    gx += (dx / dist) * force;
    gy += (dy / dist) * force;
    potential += mass / dist * 50;
  }
  const kinetic = Math.sqrt(gx*gx + gy*gy);
  const totalEnergy = potential * 0.3 + kinetic * 0.7;
  const wx = Math.sin(x*0.015 + t*0.2 + gy*0.008) * 14 + Math.cos(y*0.012 - t*0.15) * 9;
  const wy = Math.cos(y*0.015 - t*0.18 + gx*0.008) * 14 + Math.sin(x*0.013 + t*0.25) * 9;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.09, 2.2],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.11, 1.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.07, 2.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.13, 1.6],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.08, 2.8],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.1, 2.0]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }
  const act = aS/6, inh = iS/6;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
