  const eCoupling = Math.sin(totalEnergy*0.5 + t*0.8) * 0.3;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + eCoupling)*3.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.8)*0.2;
