    Math.min(255,(pal[si][1]+(pal[si+1][1]-pal[si][1])*sf)*lum*edge)|0,
    Math.min(255,(pal[si][2]+(pal[si+1][2]-pal[si][2])*sf)*lum*edge)|0
  ];
}
